const ACHIEVEMENTS=[{id:'first',name:'First Brew',icon:'🧪',desc:'Finish any level',test:p=>Object.keys(p.stars).length>0},{id:'ten',name:'Academy Graduate',icon:'🎓',desc:'Complete Level 10',test:p=>p.maxLevel>=11},{id:'perfect',name:'Flawless Formula',icon:'✨',desc:'Earn 3 stars',test:p=>Object.values(p.stars).some(x=>x===3)},{id:'gold',name:'Crystal Collector',icon:'💎',desc:'Earn 500 gold in total',test:p=>p.earned>=500},{id:'forest',name:'Forest Keeper',icon:'🌳',desc:'Complete Level 20',test:p=>p.maxLevel>=21},{id:'boss',name:'Boss Tamer',icon:'🐉',desc:'Defeat a world boss',test:p=>[10,20,30,40,50,60].some(n=>p.stars[n])},{id:'masters',name:'World Explorer',icon:'🗺️',desc:'Reach World 6',test:p=>p.maxLevel>=51},{id:'finish',name:'Master Alchemist',icon:'👑',desc:'Complete the campaign',test:p=>!!p.stars[60]}];
