const h=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rnd=(low,high)=>Math.floor(Math.random()*(high-low+1))+low;
const pick=a=>a[rnd(0,a.length-1)];
const shuffle=a=>[...a].sort(()=>Math.random()-.5);
const gcd=(a,b)=>b?gcd(b,a%b):a;
const reduced=(a,b)=>{let d=gcd(a,b);return[a/d,b/d]};
const num=n=>Number(n).toLocaleString('en-CA');
function newProfile(name){return{id:'p'+Date.now()+Math.random().toString(36).slice(2,7),name:name.slice(0,24),gold:0,earned:0,maxLevel:1,stars:{},scores:{},equipped:'classic',owned:['classic'],tutorialSeen:{},totalBrews:0,totalPerfect:0}}
function defaultStore(){const p=newProfile('Apprentice');return{profiles:[p],active:p.id,mode:'relaxed',settings:{music:true,sfx:true,musicVolume:30,sfxVolume:65,calculator:true,particles:true}}}
let store;try{store=JSON.parse(localStorage.getItem(STORAGE))||defaultStore()}catch{store=defaultStore()}
if(!store||!Array.isArray(store.profiles)||!store.profiles.length)store=defaultStore();
store.settings={music:true,sfx:true,musicVolume:30,sfxVolume:65,calculator:true,particles:true,...store.settings};
store.profiles.forEach(p=>{p.stars||={};p.scores||={};p.owned||=['classic'];p.tutorialSeen||={};p.totalPerfect||=0;p.totalBrews||=0;p.earned||=0;p.maxLevel||=1;p.equipped||='classic'});
if(!['relaxed','arcade'].includes(store.mode))store.mode='relaxed';
function profile(){return store.profiles.find(p=>p.id===store.active)||store.profiles[0]}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(store))}catch(e){console.warn('Saving unavailable:',e)}}
let view='home',chosenWorld=0,game=null,feedback=null,modalType=null,calculatorOpen=false,calcValue='0',tickHandle=null,toastHandle=null;
