/* Sound: a deliberately simple original generative soundtrack — no recordings or network dependency. */
const audio={ctx:null,musicTimer:null,step:0};
function ensureAudio(){try{if(!audio.ctx)audio.ctx=new(window.AudioContext||window.webkitAudioContext)();if(audio.ctx.state==='suspended')audio.ctx.resume()}catch(e){console.warn('Audio not supported',e)}return audio.ctx}
function note(freq,duration=.2,type='sine',gain=.1,when=0){const ctx=audio.ctx;if(!ctx)return;const osc=ctx.createOscillator(),amp=ctx.createGain(),filter=ctx.createBiquadFilter();osc.type=type;osc.frequency.setValueAtTime(freq,ctx.currentTime+when);filter.type='lowpass';filter.frequency.value=2900;amp.gain.setValueAtTime(.0001,ctx.currentTime+when);amp.gain.exponentialRampToValueAtTime(Math.max(.0002,gain),ctx.currentTime+when+.019);amp.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+when+duration);osc.connect(filter).connect(amp).connect(ctx.destination);osc.start(ctx.currentTime+when);osc.stop(ctx.currentTime+when+duration+.06)}
function sfx(type){if(!store.settings.sfx)return;ensureAudio();let g=(store.settings.sfxVolume/100)*.18;if(type==='click'){note(545,.085,'sine',g*.3);return}if(type==='drop'){note(660,.13,'triangle',g*.5);note(970,.15,'sine',g*.17,.035);return}if(type==='brew'){[310,410,550,750,980].forEach((f,i)=>note(f,.22,'sine',g*.58,i*.065));return}if(type==='correct'){[523,659,784,1046].forEach((f,i)=>note(f,.32,'sine',g*.95,i*.11));return}if(type==='wrong'){note(245,.2,'triangle',g*.45);note(195,.3,'sine',g*.4,.13);return}if(type==='unlock'){[392,493,587,784,987,1174].forEach((f,i)=>note(f,.36,'triangle',g*.5,i*.09));return}if(type==='boss'){[164,196,246].forEach((f,i)=>note(f,.55,'triangle',g*.66,i*.15))}}
function musicStep(){if(!store.settings.music||!audio.ctx||audio.ctx.state!=='running'||document.hidden)return;const scale=[261.63,329.63,392,493.88,587.33,783.99,659.26,493.88,293.66,392,440,587.33,659.26,523.25,392,329.63];let n=audio.step++%16;let v=store.settings.musicVolume/100*.028;if(n%2===0)note(scale[n],.41,'sine',v);if(n%4===0){let base=n<8?130.81:146.83;note(base,1.1,'triangle',v*.32);note(base*1.5,1.12,'sine',v*.3)}}
function syncMusic(){if(store.settings.music){ensureAudio();if(!audio.musicTimer)audio.musicTimer=setInterval(musicStep,330)}else if(audio.musicTimer){clearInterval(audio.musicTimer);audio.musicTimer=null}}

/* Math question engine: generated with verified whole-number solutions. */
function ratioPair(world){let a,b,limit=world===0?4:world>=4?8:6;do{a=rnd(1,limit);b=rnd(1,limit)}while(a===b||gcd(a,b)!==1);return[a,b]}
function ratios3(){let a,b,c;do{a=rnd(1,5);b=rnd(1,5);c=rnd(1,5)}while(gcd(gcd(a,b),c)!==1 || a===b&&b===c);return[a,b,c]}
function ingredients(n=2){return shuffle(COLORS).slice(0,n)}
function QMix(world,kind='mix'){
 let three=kind==='triple',rates=three?ratios3():ratioPair(world),k=rnd(world<2?2:2,world<3?5:7),ing=ingredients(rates.length);
 if(three){while(rates.reduce((x,y)=>x+y,0)*k>78)k=Math.max(1,k-1)}
 const amounts=rates.map(x=>x*k),total=amounts.reduce((x,y)=>x+y,0);
 const prompt=`Mix exactly ${total} crystals. Use ${ing.map(x=>x.name.toLowerCase()).join(', ')} in the ratio ${rates.join(':')}.`;
 return {type:three?'triple':'mix',kind:three?'Triple Brewing':'Crystal Mixing',title:three?'Tri-Element Elixir':'Crystal Balance Potion',prompt,ing,rates,answer:amounts,total,values:Array(rates.length).fill(0),explanation:`One ratio group has ${rates.join(' + ')} = ${rates.reduce((x,y)=>x+y,0)} crystals. ${total} ÷ ${rates.reduce((x,y)=>x+y,0)} = ${k} groups. Use ${ing.map((x,i)=>`${amounts[i]} ${x.name.toLowerCase()}`).join(', ')} crystals.`,hints:[`Add the ratio parts: ${rates.join(' + ')} = ${rates.reduce((x,y)=>x+y,0)} parts per group.`,`Divide ${total} by ${rates.reduce((x,y)=>x+y,0)} to find the number of groups.`]};
}
function QRepair(world){
 const [a,b]=ratioPair(world),k=rnd(4,9),ing=ingredients(2),targets=[a*k,b*k];
 let old1=rnd(0,Math.max(0,targets[0]-1)),old2=rnd(0,Math.max(0,targets[1]-1));
 if(old1===0&&old2===0)old1=1;
 const add=[targets[0]-old1,targets[1]-old2],total=(a+b)*k;
 return {type:'repair',kind:'Ratio Repair',title:'Rescue the Ruined Brew',prompt:`A partly brewed potion already contains ${old1} ${ing[0].name.toLowerCase()} and ${old2} ${ing[1].name.toLowerCase()} crystals. Add crystals (without removing any) to make exactly ${total} crystals in a ${a}:${b} ratio.`,ing,rates:[a,b],initial:[old1,old2],values:[0,0],answer:add,total,explanation:`The final quantities must be ${a} × ${k} = ${targets[0]} and ${b} × ${k} = ${targets[1]}. Subtract the crystals already there: add ${targets[0]} − ${old1} = ${add[0]} ${ing[0].name.toLowerCase()} and ${targets[1]} − ${old2} = ${add[1]} ${ing[1].name.toLowerCase()}.`,hints:[`The finished ${a}:${b} potion will have ${a+b} parts and ${total} crystals.`,`Find the final amount of each ingredient, then subtract what is already in the cauldron.`]}
}
function QSort(world){
 const [a,b]=ratioPair(world),k=rnd(2,6), ing=ingredients(2),correct=[a*k,b*k];
 const options=[correct];let tries=0;
 while(options.length<3&&tries++<200){let x=rnd(1,Math.max(7,a*7)),y=rnd(1,Math.max(7,b*7));if(x*b===y*a||options.some(op=>op[0]===x&&op[1]===y))continue;options.push([x,y])}
 if(options.length!==3)options.push([a*k+1,b*k],[a*k,b*k+1]);
 const scrambled=shuffle(options.map((amounts,i)=>({amounts,correct:i===0}))),answer=scrambled.findIndex(x=>x.correct);
 return{type:'sort',kind:'Potion Sorting',title:'Spot the Perfect Potion',prompt:`Which bottle has a ${a}:${b} ratio of ${ing[0].name.toLowerCase()} to ${ing[1].name.toLowerCase()} crystals?`,ing,rates:[a,b],options:scrambled,answer,selected:-1,explanation:`A ${a}:${b} ratio is equivalent to ${correct[0]}:${correct[1]} (multiply both parts by ${k}). The correct bottle has ${scrambled[answer].amounts[0]} ${ing[0].name.toLowerCase()} and ${scrambled[answer].amounts[1]} ${ing[1].name.toLowerCase()}; both quantities match the same scale factor.`,hints:[`A correct bottle must have both quantities multiplied by the same factor.`,`Try simplifying each bottle’s ratio by dividing the two numbers by their greatest common divisor.`]}
}
function QMissing(world,kind='missing'){
 const [a,b]=ratioPair(world),k=rnd(2,world>3?12:7),ing=ingredients(2),first=a*k,second=b*k;
 let totalTask=kind==='total';if(totalTask){
  let total=(a+b)*k;return{type:'value',kind:'Part-to-whole',title:'The Missing Share',prompt:`A potion has ${a}:${b} ${ing[0].name.toLowerCase()} to ${ing[1].name.toLowerCase()} crystals. There are ${total} crystals altogether. How many ${ing[1].name.toLowerCase()} crystals are needed?`,unit:'crystals',answer:second,ing,rates:[a,b],explanation:`${a} + ${b} = ${a+b} parts. ${total} ÷ ${a+b} = ${k} crystals per part. ${b} × ${k} = ${second} ${ing[1].name.toLowerCase()} crystals.`,hints:[`The total of the ratio parts is ${a} + ${b} = ${a+b}.`,`Find one part by dividing ${total} by ${a+b}.`]};
 }
 return{type:'value',kind:'Missing Ingredient',title:'Complete the Recipe',prompt:`A potion needs a ${a}:${b} ratio of ${ing[0].name.toLowerCase()} to ${ing[1].name.toLowerCase()}. You already have ${first} ${ing[0].name.toLowerCase()} crystals. How many ${ing[1].name.toLowerCase()} crystals do you need?`,unit:'crystals',answer:second,ing,rates:[a,b],explanation:`The first part is multiplied by ${k} because ${first} ÷ ${a} = ${k}. Multiply the second part by the same number: ${b} × ${k} = ${second}.`,hints:[`Find the scale factor: ${first} ÷ ${a}.`,`Multiply ${b} by the same scale factor.`]};
}
function QScale(world){
 const [a,b]=ratioPair(world),k=rnd(2,world>3?11:7),ing=ingredients(2);const target=a*k,answer=b*k;
 return{type:'value',kind:'Recipe Scaling',title:'The Growing Order',prompt:`The original recipe uses ${a} ${ing[0].name.toLowerCase()} crystals for every ${b} ${ing[1].name.toLowerCase()} crystals. A larger order uses ${target} ${ing[0].name.toLowerCase()} crystals. How many ${ing[1].name.toLowerCase()} crystals will maintain the same recipe?`,unit:'crystals',answer,ing,rates:[a,b],explanation:`${a} × ${k} = ${target}, so also multiply ${b} × ${k} = ${answer}. The equivalent ratio is ${target}:${answer}.`,hints:[`Calculate ${target} ÷ ${a} to find the recipe’s multiplier.`,`Use that multiplier on the second ingredient, ${b}.`]}
}
function QRate(world,kind='rate'){
 const unit=pick(['potion','bottle','elixir','vial']),count=rnd(3,9),each=rnd(3,13),total=count*each;
 if(kind==='unit'){
  const newCount=rnd(5,12),cost=each*newCount;
  return{type:'value',kind:'Unit-Rate Orders',title:'The Supply Merchant',prompt:`A travelling merchant sells ${count} ${unit}s for ${total} gold coins. How many gold coins do ${newCount} ${unit}s cost at the same unit price?`,answer:cost,unit:'gold coins',explanation:`${total} ÷ ${count} = ${each} gold coins per ${unit}. ${each} × ${newCount} = ${cost} gold coins.`,hints:[`Divide ${total} by ${count} to find the price for just one ${unit}.`,`Multiply the unit price by ${newCount}.`]};
 }
 return{type:'value',kind:'Unit Rates',title:'The Potion Production Line',prompt:`The alchemist uses ${total} moon-drops to make ${count} ${unit}s. At a constant rate, how many moon-drops are needed per ${unit}?`,answer:each,unit:'moon-drops per '+unit,explanation:`Unit rate = total ÷ number of ${unit}s = ${total} ÷ ${count} = ${each} moon-drops per ${unit}.`,hints:[`A unit rate is the quantity for ONE ${unit}.`,`Divide ${total} moon-drops by ${count} ${unit}s.`]}
}
function QProportion(world){
 const [a,b]=ratioPair(world),k=rnd(3,12),answer=a*k,denominator=b*k,ing=ingredients(2);
 return{type:'value',kind:'Missing-Value Proportion',title:'The Tower’s Secret Number',prompt:`The Sorcerer's Tower shows this proportion: ${a} : ${b} = x : ${denominator}. Find x to keep the ratios equivalent.`,answer,unit:'',ing,rates:[a,b],explanation:`${b} × ${k} = ${denominator}. Apply the same factor to the first part: x = ${a} × ${k} = ${answer}. Check: ${a}/${b} = ${answer}/${denominator}.`,hints:[`Find the scale factor between ${b} and ${denominator}.`,`Multiply ${a} by that same factor to find x.`]};
}
function QTriple(world){return QMix(world,'triple')}
function QAssembly(world){const jobs=[QRate(world,'unit'),QScale(world),world>3?QProportion(world):QMissing(world)];return{type:'assembly',kind:'Potion Assembly Line',title:'A Rush of Orders!',jobs,sub:0,explanation:'You completed all three assembly-line orders using unit rates and equivalent ratios.',hints:['Finish each mini-order before the next one appears.','Find the unit rate or scale factor for each order.']}}
function kindFor(world,level,step){
 const position=(level-1)%10;
 if(world===0)return pick(step===0?['mix','mix','sort']:['mix','missing','sort']);
 if(world===1)return pick(['mix','scale','sort',...(position>2?['repair']:['scale'])]);
 if(world===2)return pick(['triple','total','repair','mix','triple']);
 if(world===3)return pick(['rate','unit','scale',...(position>2?['assembly']:['unit'])]);
 if(world===4)return pick(['proportion','scale','repair','sort','total']);
 return pick(['mix','triple','repair','sort','scale','total','rate','unit','proportion','assembly']);
}
function createQuestion(world,level,step){const kind=isBoss(level) ? (step===4? ['mix','scale','triple','rate','proportion','assembly'][world] : kindFor(world,level,step)) : kindFor(world,level,step);
 switch(kind){case 'mix':return QMix(world);case 'triple':return QTriple(world);case 'repair':return QRepair(world);case 'sort':return QSort(world);case 'missing':return QMissing(world);case 'total':return QMissing(world,'total');case 'scale':return QScale(world);case 'rate':return QRate(world);case 'unit':return QRate(world,'unit');case 'proportion':return QProportion(world);case 'assembly':return QAssembly(world);default:return QMix(world)}
}
function question(){if(!game)return null;const q=game.questions[game.step];return q?.type==='assembly'?q.jobs[q.sub]:q}
function stageRoot(){return game?.questions[game.step]}
function initQuestion(){const q=question();if(q&&q.values)q.values=q.values.map(()=>0);if(q&&q.type==='sort')q.selected=-1;game.hint=0;game.stagePerfect=true;game.remaining=game.timeLimit;game.lastStarted=Date.now();}
function beginLevel(level){if(level>profile().maxLevel||level<1||level>60){toast('That level is not unlocked yet.');return}game={level,world:worldOf(level),step:0,questions:Array.from({length:isBoss(level)?5:4},(_,i)=>createQuestion(worldOf(level),level,i)),mode:store.mode,perfectCount:0,mistakes:0,hintsUsed:0,timeLimit:Math.max(47,88-worldOf(level)*6),remaining:0,stagePerfect:true,hint:0,started:Date.now()};feedback=null;initQuestion();view='play';render();startTicker();sfx(isBoss(level)?'boss':'click');const w=game.world;if(!profile().tutorialSeen[w])showModal('tutorial',{world:w,first:true});}
function startTicker(){if(tickHandle)clearInterval(tickHandle);tickHandle=setInterval(()=>{if(view!=='play'||!game||game.mode!=='arcade'||feedback||$('#overlay-root').childElementCount>0)return;game.remaining=Math.max(0,game.remaining-.25);const el=$('#timer-fill'),time=$('#timer-seconds');if(el){el.style.width=(`${game.remaining/game.timeLimit*100}%`);el.classList.toggle('hurry',game.remaining<16)}if(time)time.textContent=`${Math.ceil(game.remaining)}s`;if(game.remaining<=0)timeOut()},250)}
function stopTicker(){if(tickHandle){clearInterval(tickHandle);tickHandle=null}}
function timeOut(){if(!game||feedback)return;game.mistakes++;game.stagePerfect=false;const q=question();feedback={ok:false,timeout:true,title:'Time is up!',message:'The customer will come back another day. Review the solution and try the next order.',detail:q.explanation||stageRoot().explanation,skip:true};sfx('wrong');render()}
function currentCustomer(){return isBoss(game.level)?CUSTOMERS[(game.world+4)%CUSTOMERS.length]:CUSTOMERS[(game.level+game.step*3)%CUSTOMERS.length]}
function awardAchievementText(before){const after=ACHIEVEMENTS.filter(a=>a.test(profile())).map(a=>a.id);const diff=after.filter(x=>!before.includes(x));if(diff.length)setTimeout(()=>toast(`🏆 Achievement: ${ACHIEVEMENTS.find(a=>a.id===diff[0]).name}`),500)}
function finishStage(perfect){const q=question();if(stageRoot().type==='assembly'&&perfect&&stageRoot().sub+1<stageRoot().jobs.length){stageRoot().sub++;game.hint=0;game.remaining=game.timeLimit;toast(`Assembly order ${stageRoot().sub} complete! Next vial ready.`);sfx('drop');render();return}
 if(game.stagePerfect)game.perfectCount++;
 profile().totalBrews++;if(game.stagePerfect)profile().totalPerfect++;
 feedback={ok:true,title:stageRoot().type==='assembly'?'Assembly Line Complete!':'Potion Perfect!',message:game.stagePerfect?'Flawless! Your first attempt was right.':'Well done! You mastered this mixture after some practice.',detail:stageRoot().type==='assembly'?'All three mini-orders are complete. '+stageRoot().explanation:q.explanation};sfx('correct');render()}
function handleBrew(){if(!game||view!=='play'||feedback)return;const q=question();if(!q)return;
 let correct=false,diagnosis='';
 if(['mix','triple','repair'].includes(q.type)){
  const inputs=[...document.querySelectorAll('.qty-input')];if(inputs.length){q.values=inputs.map((el)=>Math.max(0,Math.min(999,Math.floor(Number(el.value)||0))))}
  correct=q.values.every((x,i)=>x===q.answer[i]);const combined=q.values.reduce((a,b)=>a+b,0)+(q.initial?.reduce((a,b)=>a+b,0)||0);
  diagnosis=`Your current mixture has ${combined} of ${q.total} required crystals. ${q.type==='repair'?'Remember to subtract the starting ingredients.':'Add the ratio parts to work out each share.'}`;
 }else if(q.type==='sort'){correct=q.selected===q.answer;diagnosis=q.selected<0?'Choose one of the three bottles first.':'Try simplifying the two quantities in each bottle.';if(q.selected<0){toast(diagnosis);return}}
 else if(q.type==='value'){
  const el=$('[data-answer]');if(!el||!el.value.trim()){toast('Enter a number before brewing.');el?.focus();return}
  const n=Number(el.value);if(!Number.isFinite(n)){toast('Please enter a valid number.');return}correct=Math.abs(n-q.answer)<1e-8;diagnosis='Check the scale factor or number of parts, and try again.';
 }
 if(correct){finishStage(true)}else{game.mistakes++;game.stagePerfect=false;feedback={ok:false,title:'Not quite — keep experimenting!',message:diagnosis,detail:q.explanation,skip:false};sfx('wrong');render()}
}
function continueStage(){if(!game||!feedback)return;
 const skip=feedback.skip;
 feedback=null;
 if(skip||stageRoot().type!=='assembly'||stageRoot().sub===stageRoot().jobs.length){game.step++;if(game.step>=game.questions.length){finishLevel();return}initQuestion();render();return}
 // Assembly feedback only appears after the last mini-job.
 game.step++;if(game.step>=game.questions.length){finishLevel();return}initQuestion();render();
}
function finishLevel(){const before=ACHIEVEMENTS.filter(a=>a.test(profile())).map(a=>a.id);const p=profile(),g=game;const stars=g.perfectCount===g.questions.length?3:g.perfectCount>=Math.ceil(g.questions.length*.60)?2:1;
 const gold=20+g.perfectCount*16+(g.mode==='arcade'?20:0)+(isBoss(g.level)?35:0);
 p.gold+=gold;p.earned+=gold;p.maxLevel=Math.max(p.maxLevel,Math.min(61,g.level+1));p.stars[g.level]=Math.max(stars,p.stars[g.level]||0);p.scores[`${g.level}-${g.mode}`]=Math.max(g.perfectCount,p.scores[`${g.level}-${g.mode}`]||0);persist();game={...g,awardedStars:stars,awardGold:gold};view='finish';stopTicker();sfx(isBoss(g.level)?'unlock':'correct');render();awardAchievementText(before)}
function useHint(){if(!game||feedback)return;const q=question();if(!q)return;if(game.hint>=q.hints.length){toast('All hints for this order are showing.');return}game.hint++;game.hintsUsed++;game.stagePerfect=false;render();sfx('click')}
function adjustGem(index,delta){const q=question();if(!q||!q.values)return;if(delta>0)animateIngredient(index);q.values[index]=Math.max(0,Math.min(999,q.values[index]+delta));const inp=document.querySelector(`.qty-input[data-index="${index}"]`);if(inp)inp.value=q.values[index];updateTotals();sfx('drop')}
function animateIngredient(index){
  if(!store.settings.particles)return;
  const origin=document.querySelector(`.ingredient-card img[data-index="${index}"]`),target=document.querySelector('.cauldron-wrap');
  if(!origin||!target||typeof origin.animate!=='function')return;
  const src=origin.getBoundingClientRect(),dst=target.getBoundingClientRect();
  const gem=document.createElement('img');gem.src=origin.src;gem.alt='';gem.style.cssText=`position:fixed;left:${src.left}px;top:${src.top}px;width:40px;height:40px;z-index:42;pointer-events:none;filter:drop-shadow(0 0 9px #ffecb9)`;
  document.body.append(gem);
  const anim=gem.animate([{transform:'translate(0px,0px) rotate(0deg) scale(1)',opacity:1},{transform:`translate(${dst.left+dst.width*.5-src.left-20}px,${dst.top+dst.height*.4-src.top-20}px) rotate(320deg) scale(.4)`,opacity:.2}],{duration:510,easing:'cubic-bezier(.2,.8,.2,1)'});
  anim.onfinish=()=>gem.remove();anim.oncancel=()=>gem.remove();
}
function updateTotals(){const q=question();if(!q||!q.values)return;const sum=q.values.reduce((a,b)=>a+b,0)+(q.initial?.reduce((a,b)=>a+b,0)||0);const label=$('#mix-total');if(label)label.textContent=`${sum} / ${q.total} crystals`;const meter=$('#mix-bar');if(meter)meter.style.width=`${Math.min(100,100*sum/q.total)}%`;const soup=$('.soup-halo');if(soup)soup.style.filter=`hue-rotate(${sum%24*9}deg)`}
function selectBottle(index){const q=question();if(!q||q.type!=='sort')return;q.selected=index;document.querySelectorAll('.choice-bottle').forEach((el,i)=>{el.classList.toggle('selected',i===index);el.setAttribute('aria-pressed',String(i===index))});sfx('click')}
/* Screen building */
function icon(name){const icons={home:'⌂',map:'◈',shop:'✧',help:'?',settings:'⚙',gold:'✦',star:'★',back:'‹',pause:'Ⅱ',music:'♫',clock:'◷',calculator:'▦'};return icons[name]||name}
function header(){const p=profile();const nav=[['home','Home','⌂'],['map','World Map','◈'],['shop','Potion Shop','✧']];return `<button class="brand" data-action="nav" data-view="home" aria-label="Potion Panic home"><span class="brand-mark"><img src="${gemImg('amethyst')}" alt=""/></span><span><span class="brand-title">Potion Panic</span><span class="brand-sub">The Alchemist’s Academy</span></span></button><nav class="header-nav" aria-label="Main navigation">${nav.map(([id,label,glyph])=>`<button class="nav-btn ${view===id||view==='world'&&id==='map'?'active':''}" data-action="nav" data-view="${id}" title="${label}">${glyph} <span class="nav-word">${label}</span></button>`).join('')}<button class="nav-btn" data-action="modal" data-modal="how" title="How to play">❔ <span class="nav-word">Help</span></button></nav><div class="header-right"><span class="gold-chip" title="Coins earned through gameplay">✦ ${num(p.gold)}</span><button class="profile-chip" data-action="modal" data-modal="profiles" title="Switch student profile">${h(p.name)}</button><button class="nav-btn" data-action="modal" data-modal="settings" title="Settings">⚙</button></div>`}
function render(){const page=$('#screen');$('#topbar').innerHTML=header();page.innerHTML=view==='home'?homePage():view==='map'?mapPage():view==='world'?worldPage():view==='shop'?shopPage():view==='play'?gamePage():view==='finish'?finishPage():homePage();renderCalc();}
function homePage(){const p=profile(),done=Object.keys(p.stars).length,progress=Math.min(60,p.maxLevel),lvl=progress;
 return `<div class="screen-wrap"><section class="hero"><div class="hero-copy"><div class="eyebrow">A magical mathematics adventure</div><h1 class="hero-title">Potion <span>Panic!</span></h1><p class="hero-description">Welcome, <strong>${h(p.name)}</strong>! Stir sparkling crystals, rescue magical recipes, outwit extraordinary bosses, and become the greatest alchemist in six enchanted worlds. Every potion has a secret: <strong>the perfect ratio.</strong></p><div class="hero-actions"><button class="btn btn-primary btn-large" data-action="start" data-level="${lvl}">✦ ${done?'Continue Adventure':'Start Adventure'}</button><button class="btn btn-ghost btn-large" data-action="nav" data-view="map">◈ Explore Worlds</button></div><div class="hero-points"><span class="hero-point">✦ 60 unique levels</span><span class="hero-point">◷ Relaxed + Arcade</span><span class="hero-point">⚗ Boss potion battles</span><span class="hero-point">✓ Saves offline</span></div></div><div class="hero-art" aria-hidden="true"><img class="hero-bg" src="${sceneImg(Math.min(5,worldOf(lvl)))}"/><img class="hero-cauldron" src="${A}cauldron.svg"/><img class="hero-character" src="${faceImg('ember')}"/><div class="hero-float"><small>THE SECRET RECIPE</small>2 ruby : 3 azure<br/>✦ perfect harmony</div><span class="hero-spark a">✦</span><span class="hero-spark b">✧</span><span class="hero-spark c">✦</span></div></section><div class="overview"><div class="overview-card"><div class="overview-icon">🗺️</div><strong>${done}<span style="font-size:15px"> / 60</span></strong><small>Levels completed</small></div><div class="overview-card"><div class="overview-icon">⭐</div><strong>${Object.values(p.stars).reduce((a,b)=>a+b,0)}</strong><small>Stars earned</small></div><div class="overview-card"><div class="overview-icon">🏆</div><strong>${ACHIEVEMENTS.filter(x=>x.test(p)).length}<span style="font-size:15px"> / ${ACHIEVEMENTS.length}</span></strong><small>Achievements unlocked</small></div></div><div class="section-heading"><div><h2>Your Alchemist’s Journey</h2><p>Make your way through six magical realms. New worlds unlock as you grow.</p></div><button class="btn btn-ghost btn-small" data-action="nav" data-view="map">Open Map →</button></div><div class="world-grid">${[0,1,2].map(w=>worldCard(w)).join('')}</div></div>`}
function worldCard(w){const world=WORLDS[w],p=profile(),start=w*10+1,unlocked=p.maxLevel>=start,completed=Array.from({length:10},(_,i)=>start+i).filter(n=>p.stars[n]).length;
 return `<article class="world-card ${unlocked?'':'locked'}"><div class="world-banner" style="background-image:url('${sceneImg(w)}')"><span class="world-badge">WORLD ${w+1} · ${world.symbol}</span>${unlocked?'':`<span class="lock-screen">🔒 Unlock at Level ${start}</span>`}</div><div class="world-content"><h3 class="world-name">${world.name}</h3><p class="world-desc">${world.desc}</p><div class="world-progress"><span>${world.concept}</span><strong>${completed}/10 levels</strong></div><div class="progress-track"><div class="progress-fill" style="width:${completed*10}%"></div></div><div class="world-actions"><button class="btn ${unlocked?'btn-primary':'btn-muted'} btn-small" data-action="world" data-world="${w}" ${unlocked?'':'disabled'}>${unlocked?'Explore World →':'Locked 🔒'}</button></div></div></article>`}
function modeSwitch(){return `<div class="mode-switch" role="group" aria-label="Gameplay mode"><button data-action="mode" data-mode="relaxed" class="${store.mode==='relaxed'?'selected':''}" aria-pressed="${store.mode==='relaxed'}">☀ Relaxed</button><button data-action="mode" data-mode="arcade" class="${store.mode==='arcade'?'selected':''}" aria-pressed="${store.mode==='arcade'}">◷ Arcade</button></div>`}
function mapPage(){const p=profile(),total=Object.values(p.stars).reduce((a,b)=>a+b,0);return `<div class="screen-wrap"><div class="section-heading"><div><div class="eyebrow">Chart your destiny</div><h1>Choose Your World</h1><p>There are 10 levels in each world, including a final boss. Complete levels in order to unlock the next.</p></div></div><div class="map-toolbar">${modeSwitch()}<span class="tiny-chip">★ ${total} stars collected</span></div><div class="world-grid">${WORLDS.map((_,i)=>worldCard(i)).join('')}</div></div>`}
function worldPage(){const w=chosenWorld,world=WORLDS[w],p=profile(),start=w*10+1;return `<div class="screen-wrap"><button class="back-link" data-action="nav" data-view="map">← Back to World Map</button><div class="world-detail-hero" style="background-image:url('${sceneImg(w)}')"><div class="world-detail-copy"><div class="eyebrow">World ${w+1} of 6 · ${world.concept}</div><h1>${world.name}</h1><p>${world.desc} ${STORY[w][1]}</p></div></div><div class="map-toolbar">${modeSwitch()}<span class="tiny-chip">★ Select a level to enter the laboratory</span></div><div class="level-grid">${Array.from({length:10},(_,i)=>{const lv=start+i,unlocked=p.maxLevel>=lv,stars=p.stars[lv]||0,boss=isBoss(lv);return `<button class="level-card ${boss?'boss':''} ${unlocked&&lv===p.maxLevel?'active':''}" data-action="start" data-level="${lv}" ${unlocked?'':'disabled'} title="${boss?'Boss challenge: ':''}Level ${lv}${unlocked?'':' — locked'}">${boss?'<span class="level-boss-icon">👑</span>':''}<span class="level-num">${unlocked?lv:'🔒'}</span><span class="level-sub">${boss?'WORLD BOSS':unlocked?'LEVEL '+lv:'LOCKED'}</span><span class="level-stars stars ${stars?'':'empty'}">${stars?'★'.repeat(stars)+'☆'.repeat(3-stars):'☆☆☆'}</span></button>`}).join('')}</div></div>`}
function shopPage(){const p=profile();return `<div class="screen-wrap"><div class="section-heading"><div><div class="eyebrow">Spend your hard-earned gold</div><h1>Alchemist’s Emporium</h1><p>Customise your cauldron without giving up any mathematical challenge. Cosmetics never change your answers.</p></div><span class="gold-chip">✦ ${num(p.gold)} gold</span></div><div class="shop-grid">${SKINS.map(s=>{const own=p.owned.includes(s.id),equipped=p.equipped===s.id;return `<article class="shop-card ${equipped?'equipped':''}"><div class="shop-image"><img class="${s.id}" style="${s.id==='classic'?'':`filter:hue-rotate(${({dawn:35,glacier:68,inferno:233,cosmic:298})[s.id]}deg)`}" src="${A}cauldron.svg" alt="${s.name} illustration"/></div><h3>${s.name}</h3><p>${s.desc}</p><div class="shop-price">${own?'✓ Owned':`✦ ${s.cost} gold`}</div><button class="btn ${equipped?'btn-emerald':own?'btn-ghost':'btn-primary'}" data-action="purchase" data-skin="${s.id}" ${equipped?'disabled':''}>${equipped?'✓ Equipped':own?'Equip':'Purchase'}</button></article>`}).join('')}</div><div class="section-heading" style="margin-top:38px"><div><h2>Achievement Cabinet</h2><p>Collect magical badges as you progress.</p></div></div><div class="achievement-grid">${ACHIEVEMENTS.map(a=>`<article class="achievement ${a.test(p)?'':'unearned'}"><span class="medal">${a.test(p)?a.icon:'🔒'}</span><div><h3>${a.name}</h3><p>${a.desc}</p></div></article>`).join('')}</div></div>`}
function qDetails(q){const ing=q.ing||[],ratio=q.rates;return ratio?`<div class="math-ratio">${ratio.map((n,i)=>`<span class="ratio-token" style="border-bottom:3px solid ${ing[i]?.tone||'#e6bd82'}">${h(ing[i]?.name||'Part '+(i+1))} ${n}</span>`).join('')}</div>`:''}
function workspace(){const q=question(),root=stageRoot();if(!q)return'';
 if(['mix','triple','repair'].includes(q.type)){return `<div class="ingredient-dock"><div class="dock-title"><span>✦ ${q.type==='repair'?'Add ingredients':'Ingredient tray'} <small>(tap a gem to add 1)</small></span><span id="mix-total">${q.initial?.reduce((a,b)=>a+b,0)||0} / ${q.total} crystals</span></div><div class="progress-track" style="margin-bottom:7px"><div class="progress-fill" id="mix-bar" style="width:${((q.initial?.reduce((a,b)=>a+b,0)||0)/q.total)*100}%"></div></div><div class="ingredient-row" style="--ingredient-count:${q.ing.length}">${q.ing.map((x,i)=>`<div class="ingredient-card"><img src="${gemImg(x.id)}" alt="Add one ${x.name.toLowerCase()} crystal" data-action="adjust" data-index="${i}" data-delta="1" title="Tap to add, or drag into the cauldron" draggable="true" data-gem-drag="${i}" role="button" tabindex="0"/><span class="ingredient-label">${x.name} ${q.initial?`(+ to ${q.initial[i]})`:''}</span><div class="ingredient-controls"><button class="step-btn" data-action="adjust" data-index="${i}" data-delta="-1" aria-label="Remove one ${x.name} crystal">−</button><input class="qty-input" data-index="${i}" type="number" inputmode="numeric" min="0" max="999" value="${q.values[i]}" aria-label="${x.name} crystals ${q.initial?'to add':'in mixture'}"/><button class="step-btn" data-action="adjust" data-index="${i}" data-delta="1" aria-label="Add one ${x.name} crystal">+</button><button class="step-btn" data-action="adjust" data-index="${i}" data-delta="5" aria-label="Add five ${x.name} crystals" title="Add five">+5</button></div></div>`).join('')}</div></div>`}
 if(q.type==='sort')return `<div class="choice-scene"><div class="choice-heading">Which potion has the correct ratio?</div><div class="choice-row">${q.options.map((o,i)=>`<button class="choice-bottle ${q.selected===i?'selected':''}" data-action="bottle" data-index="${i}" aria-pressed="${q.selected===i}"><div class="bottle-shape" style="--liquid:${q.ing[0].tone};--liquid-2:${q.ing[1].tone};--split:${Math.round(o.amounts[0]/(o.amounts[0]+o.amounts[1])*70)}%"></div><strong>Bottle ${String.fromCharCode(65+i)}</strong><span>${o.amounts[0]} ${q.ing[0].name} · ${o.amounts[1]} ${q.ing[1].name}</span></button>`).join('')}</div><div class="mini-pill">Tap a bottle, then press Brew Potion</div></div>`;
 const sub=root.type==='assembly'?`<div class="mini-pill">Assembly-line bottle ${root.sub+1} of ${root.jobs.length}</div>`:'';
 return `<div class="numeric-workspace"><div class="numeric-kicker">✦ ${q.kind}</div>${sub}<div class="numeric-question">${h(q.prompt)}</div><div class="numeric-input-wrap"><input data-answer id="numeric-answer" class="numeric-input" type="number" inputmode="decimal" step="any" placeholder="?" autocomplete="off" aria-label="Your numeric answer"/><span class="numeric-unit">${h(q.unit||'')}</span></div><div class="work-sample">Think: What does one part—or one unit—represent?</div></div>`;
}
function gamePage(){const g=game,w=WORLDS[g.world],p=profile(),root=stageRoot(),q=question(),customer=currentCustomer(),boss=isBoss(g.level),score=g.perfectCount;
 return `<div class="play-shell"><div class="play-toolbar"><div class="play-titleline"><button class="btn btn-muted btn-small" data-action="pause">Ⅱ Pause</button><strong>${w.name}</strong><small>Level ${g.level} ${boss?'• BOSS':''}</small></div><div class="play-tools"><span class="tiny-chip">${g.mode==='arcade'?'◷ Arcade':'☀ Relaxed'}</span>${store.settings.calculator?`<button class="btn btn-muted btn-small" data-action="calculator" title="Open calculator">▦ Calculator</button>`:''}<button class="btn btn-muted btn-small" data-action="modal" data-modal="how">? Help</button></div></div><div class="play-columns"><aside class="side-panel left"><section class="panel order-panel"><div class="panel-label">✦ A special order has arrived</div><div class="customer"><img class="customer-avatar" src="${boss?bossImg(g.world):faceImg(customer.face)}" alt="${boss?w.boss:customer.name}"/><div><div class="customer-name">${boss?w.boss:customer.name}</div><div class="customer-line">“${boss?w.speech:customer.phrase}”</div></div></div><div class="order-scroll"><div class="scroll-kicker">Order ${g.step+1}/${g.questions.length} · ${root.kind}</div><h2>${boss?`${w.symbol} `:''}${root.title}</h2><p>${h(root.type==='assembly'?'Complete these three connected orders to keep the production line moving!':q.prompt)}</p>${root.type==='assembly'?`<div style="margin-top:8px;border-top:1px solid #88696b;padding-top:8px"><p>${h(q.prompt)}</p><strong>${root.sub+1} / ${root.jobs.length} mini-orders</strong></div>`:''}</div>${qDetails(q)}</section><section class="panel hint-panel"><div class="panel-title">✧ Wizard’s Wisdom</div><p style="margin-top:7px">${g.world===0?'A ratio compares quantities in the order they are written.':g.world===1?'Multiply all ratio parts by the SAME number.':g.world===2?'Total parts are found by adding the ratio numbers.':g.world===3?'Find the amount for one unit first.':g.world===4?'Both sides of a proportion represent equivalent ratios.':'Take your time to identify the relationship first.'}</p>${g.hint?`<div class="hint-reveal">${q.hints.slice(0,g.hint).map((x,i)=>`<div><strong>Hint ${i+1}:</strong> ${h(x)}</div>`).join('')}</div>`:''}<button class="btn btn-ghost btn-small" data-action="hint" ${feedback?'disabled':''}>✦ ${g.hint?q.hints.length===g.hint?'All hints revealed':'Another hint':'Need a hint?'}</button></section></aside><section class="scene" aria-label="Illustrated potion laboratory"><img class="scene-bg" src="${sceneImg(g.world)}" alt=""/><div class="scene-magic"></div><div class="scene-label"><span>${boss?'★ BOSS TRIAL':w.symbol+' '+w.short}</span>${q.kind}</div><div class="cauldron-wrap ${feedback?.ok?'brewing':''}"><img class="${p.equipped==='classic'?'':p.equipped}" src="${A}cauldron.svg" alt="Illustrated magical cauldron"/><div class="soup-halo ${feedback?.ok?'brewing':''}"></div>${store.settings.particles?'<span class="bubble b1"></span><span class="bubble b2"></span><span class="bubble b3"></span><span class="bubble b4"></span>':''}</div><img class="scene-character" src="${faceImg('ember')}" alt=""/><span class="magic-spark one">✦</span><span class="magic-spark two">✧</span><span class="magic-spark three">✦</span>${boss?`<div class="scene-boss"><img src="${bossImg(g.world)}" alt=""/><strong>${w.boss}</strong><small>Trial ${g.step+1}/${g.questions.length}</small></div>`:''}${workspace()}${feedback?feedbackHtml():''}</section><aside class="side-panel right"><section class="panel stage-panel"><div class="panel-title">✦ Brewing Progress</div><div class="stage-numbers"><strong>Level ${g.level}</strong><span>Order ${g.step+1} of ${g.questions.length}</span></div><div class="stage-steps">${g.questions.map((_,i)=>`<div class="stage-dot ${i<g.step?'done':i===g.step?'current':''}"></div>`).join('')}</div>${g.mode==='arcade'?`<div class="timer-box"><div class="timer-top"><span>⏳ Customer patience</span><strong id="timer-seconds">${Math.ceil(g.remaining)}s</strong></div><div class="timer-track"><div id="timer-fill" class="timer-fill ${g.remaining<16?'hurry':''}" style="width:${100*g.remaining/g.timeLimit}%"></div></div></div>`:'<div class="guide-card"><strong>☀ Relaxed Mode</strong><p>No timer. Experiment with different quantities, and use hints whenever you need them.</p></div>'}<div class="stat-line"><span>Perfect orders</span><strong>${score} / ${g.questions.length}</strong></div><div class="stat-line"><span>Attempts to improve</span><strong>${g.mistakes}</strong></div><div class="stat-line"><span>Hints used</span><strong>${g.hintsUsed}</strong></div>${boss?`<div class="guide-card"><strong>👑 Boss encounter</strong><p>Complete all ${g.questions.length} stages to defeat ${w.boss} and unlock the next world.</p></div>`:''}</section><section class="panel brew-control"><div class="panel-label" style="margin-bottom:10px">${['mix','repair','triple'].includes(q.type)?'Measure your ingredients':'Check your solution'}</div><button class="btn btn-emerald btn-large btn-wide" data-action="brew" ${feedback?'disabled':''}>⚗ ${q.type==='sort'?'Check Bottle':q.type==='value'?'Submit Answer':'Brew Potion!'}</button><div class="play-footer" style="margin-top:13px"><span>✦ Correct ratios earn stars</span><span>${g.mode==='arcade'?'◷ Timed':'☀ Untimed'}</span></div></section></aside></div></div>`
}
function feedbackHtml(){const f=feedback;return `<div class="feedback-cover" role="status" aria-live="polite"><div class="feedback-card"><div class="feedback-icon">${f.ok?'✨':'🧙‍♂️'}</div><h2>${f.title}</h2><p>${h(f.message)}</p><div class="feedback-answer"><strong>✦ How the mathematics works</strong><br/>${h(f.detail||'Review the recipe and check your proportions.')}</div>${f.ok||f.skip?`<button class="btn btn-primary btn-wide" data-action="continue">${game.step===game.questions.length-1?'Complete Level →':'Next Order →'}</button>`:`<button class="btn btn-emerald btn-wide" data-action="retry">Try Again →</button>`}</div></div>`}
function finishPage(){const g=game,p=profile(),stars=g.awardedStars,world=WORLDS[g.world],final=g.level===60;return `<div class="finish-screen"><article class="finish-card"><div class="eyebrow">${isBoss(g.level)?'WORLD BOSS DEFEATED':'LEVEL COMPLETE'}</div><div class="finish-crown">${final?'👑':isBoss(g.level)?'🏆':'⚗️'}</div><h1>${final?'Master Alchemist!':isBoss(g.level)?'The Realm Is Safe!':'A Brilliant Batch!'}</h1><div class="finish-stars" aria-label="${stars} stars out of 3">${'★'.repeat(stars)}<span style="opacity:.3">${'★'.repeat(3-stars)}</span></div><p>${final?'You completed all six worlds and mastered the full Potion Panic adventure!':isBoss(g.level)?`You out-brewed ${world.boss}. Your next enchanted world is ready to explore!`:`Level ${g.level} is complete. Your potion shop is growing stronger with every balanced mixture.`}</p><div class="finish-stats"><div class="finish-stat"><strong>${g.perfectCount}/${g.questions.length}</strong><small>First-try orders</small></div><div class="finish-stat"><strong>✦ ${g.awardGold}</strong><small>Gold earned</small></div><div class="finish-stat"><strong>${g.mistakes}</strong><small>Practice attempts</small></div></div><p style="font-size:12px">Best stars on this level: ${'★'.repeat(p.stars[g.level]||0)}. Your progress has been saved on this device.</p><div class="btn-row"><button class="btn btn-ghost" data-action="replay">↻ Replay Level</button><button class="btn btn-primary" data-action="next-level">${final?'World Map':`Continue to Level ${g.level+1} →`}</button></div></article></div>`}
/* Dialogs and interactions */
let modalOptions={},confirmAction=null,calcLeft=null,calcTop=null;
function modalShell(title,body,wide=false,buttons=''){return `<div class="overlay" role="presentation"><section class="modal ${wide?'big':''}" role="dialog" aria-modal="true" aria-label="${h(title)}"><div class="modal-head"><h2>${title}</h2><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button></div>${body}${buttons}</section></div>`}
function modalHtml(type,opts){
 if(type==='how')return modalShell('✦ How to Play',`<p>Welcome to <strong>Potion Panic</strong>, the magical ratio adventure! Each order has a correct ratio. Read the customer’s instructions, then brew the potion or choose the solution.</p><h3>1. Crystal Mixing & Repair</h3><p>Tap an ingredient gem to add one crystal, use <strong>+ / − / +5</strong> buttons, or type a quantity directly. A ratio of <strong>2:3</strong> means 2 of the first ingredient for every 3 of the second. Add both parts to find the total.</p><h3>2. Other magical challenges</h3><p><strong>Sorting:</strong> select the bottle with the right ratio. <strong>Recipe Scaling:</strong> grow or shrink quantities by the same factor. <strong>Three-part potions:</strong> balance all three ingredients. <strong>Unit Rates & Proportions:</strong> type the number that completes the recipe. <strong>Assembly Lines:</strong> solve three smaller orders in a row.</p><h3>3. Modes, stars, and bosses</h3><p><strong>Relaxed</strong> mode has no time limit. <strong>Arcade</strong> mode challenges you to beat a customer timer. Every completed level earns at least one star; more first-attempt successes earn two or three. Every tenth level is a multi-stage boss challenge.</p><h3>4. Student tools</h3><p>Use Wizard’s Wisdom for hints, and open the optional draggable calculator if you need it. To enter values, type in the answer box and press Enter or Submit. Your stars, gold, cosmetics, and unlocked levels save in this browser for your selected profile.</p><div class="modal-actions"><button class="btn btn-primary" data-action="close-modal">Let’s Brew! ⚗</button></div>`,true);
 if(type==='tutorial'){
  let w=opts.world??0,l=LESSONS[w];return modalShell(`📜 ${l.title}`,`<div class="eyebrow">World ${w+1} · ${WORLDS[w].name}</div><div style="display:grid;grid-template-columns:minmax(0,1fr) 145px;gap:15px;align-items:center;margin:18px 0"><p>${l.body}</p><img src="${sceneImg(w)}" alt="${WORLDS[w].name} illustrated laboratory" style="aspect-ratio:1/1;object-fit:cover;border-radius:15px;border:2px solid #dfbf88"/></div><div class="guide-card"><strong>✦ Worked example</strong><p>${l.example}</p></div><p style="margin-top:13px"><strong>Remember:</strong> ${l.tip}</p><div class="modal-actions"><button class="btn btn-primary" data-action="close-modal">Enter the Laboratory →</button></div>`);
 }
 if(type==='pause')return modalShell('Ⅱ Potion Brewing Paused',`<p>Take your time! The game and arcade countdown are paused while this window is open.</p><p style="margin-top:8px">Your level progress is recorded when you complete the level. Leaving now will discard unfinished orders, but previously completed levels remain saved.</p><div class="modal-actions"><button class="btn btn-ghost" data-action="exit-level">Return to World Map</button><button class="btn btn-primary" data-action="close-modal">Resume Brewing →</button></div>`);
 if(type==='settings')return modalShell('⚙ Game Settings',`<p>These settings are saved locally and apply to every student profile on this device.</p><div class="settings-row"><div><strong>Background Music</strong><small>Original magical ambient melody</small></div><button class="toggle ${store.settings.music?'on':''}" data-action="toggle-setting" data-setting="music">${store.settings.music?'On':'Off'}</button></div><div class="settings-row"><div><strong>Music Volume</strong></div><input class="slider" type="range" data-setting-range="musicVolume" min="0" max="100" value="${store.settings.musicVolume}" aria-label="Music volume"/><span>${store.settings.musicVolume}%</span></div><div class="settings-row"><div><strong>Sound Effects</strong><small>Bubbling, crystals, rewards, and victories</small></div><button class="toggle ${store.settings.sfx?'on':''}" data-action="toggle-setting" data-setting="sfx">${store.settings.sfx?'On':'Off'}</button></div><div class="settings-row"><div><strong>Sound Effects Volume</strong></div><input class="slider" type="range" data-setting-range="sfxVolume" min="0" max="100" value="${store.settings.sfxVolume}" aria-label="Sound effects volume"/><span>${store.settings.sfxVolume}%</span></div><div class="settings-row"><div><strong>Optional Calculator</strong><small>Available in the laboratory; drag it anywhere</small></div><button class="toggle ${store.settings.calculator?'on':''}" data-action="toggle-setting" data-setting="calculator">${store.settings.calculator?'On':'Off'}</button></div><div class="settings-row"><div><strong>Animated Bubbles</strong><small>Turn off on older phones to improve speed</small></div><button class="toggle ${store.settings.particles?'on':''}" data-action="toggle-setting" data-setting="particles">${store.settings.particles?'On':'Off'}</button></div><div class="modal-actions"><button class="btn btn-primary" data-action="close-modal">Done</button></div>`);
 if(type==='profiles')return modalShell('👤 Student Profiles',`<p>Each learner keeps their own levels, stars, gold, and upgrades on this browser. Up to 8 profiles can be saved here.</p><div class="profiles-list" style="margin:16px 0">${store.profiles.map(p=>`<div class="profile-row ${store.active===p.id?'active':''}"><span style="font-size:20px">🧙</span><strong>${h(p.name)}<small style="display:block;font-size:10px;margin-top:5px">Level ${Math.min(p.maxLevel,60)} · ${Object.keys(p.stars).length} completed</small></strong><button class="btn btn-${store.active===p.id?'emerald':'ghost'} btn-small" data-action="profile-switch" data-id="${h(p.id)}" ${store.active===p.id?'disabled':''}>${store.active===p.id?'✓ Active':'Select'}</button><button class="btn btn-muted btn-small" data-action="profile-delete" data-id="${h(p.id)}" title="Delete this profile" ${store.profiles.length===1?'disabled':''}>✕</button></div>`).join('')}</div><label for="new-profile" class="field-label">Add a new student</label><div class="btn-row"><input class="text-field" id="new-profile" maxlength="24" placeholder="Student name or nickname"/><button class="btn btn-primary" data-action="profile-add" ${store.profiles.length>=8?'disabled':''}>+ Add</button></div><p style="font-size:11px;margin-top:9px">Profiles are local to this browser. Clearing browser data can erase progress.</p>`);
 if(type==='confirm')return modalShell(h(opts.title||'Are you sure?'),`<p>${h(opts.message||'This action cannot be undone.')}</p><div class="modal-actions"><button class="btn btn-ghost" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="confirm-yes">${h(opts.confirmLabel||'Confirm')}</button></div>`);
 return'';
}
function showModal(type,options={}){modalType=type;modalOptions=options;$('#overlay-root').innerHTML=modalHtml(type,options);if(type==='profiles')$('#new-profile')?.focus()}
function closeModal(){if(modalType==='tutorial'&&modalOptions.first&&game){profile().tutorialSeen[game.world]=true;persist()}modalType=null;modalOptions={};$('#overlay-root').innerHTML='';}
function confirmDialog(title,message,callback,confirmLabel='Confirm'){confirmAction=callback;showModal('confirm',{title,message,confirmLabel})}
function toast(message){const target=$('#toast-stack'),t=document.createElement('div');t.className='toast';t.textContent=message;target.appendChild(t);setTimeout(()=>t.remove(),3600)}
function navigate(to){if(view==='play'&&game){confirmDialog('Leave the Laboratory?','Your finished levels remain saved, but you will lose progress on this unfinished level.',()=>{game=null;feedback=null;stopTicker();calculatorOpen=false;view=to;render()},'Leave Level');return}view=to;render()}
function purchase(skin){let s=SKINS.find(x=>x.id===skin),p=profile();if(!s)return;if(p.owned.includes(skin)){p.equipped=skin;persist();sfx('unlock');toast(`${s.name} equipped!`);render();return}if(p.gold<s.cost){toast(`You need ${s.cost-p.gold} more gold to buy this.`);return}confirmDialog('Purchase '+s.name+'?',`Spend ${s.cost} gold coins on this cosmetic cauldron? It will not change the math difficulty.`,()=>{const curr=profile();if(curr.gold<s.cost)return;curr.gold-=s.cost;curr.owned.push(s.id);curr.equipped=s.id;persist();sfx('unlock');render();toast(`${s.name} unlocked and equipped!`)},'Buy for '+s.cost+' gold')}
function newStudent(){let el=$('#new-profile'),name=el?.value.trim().replace(/\s+/g,' ');if(!name){toast('Please enter a student name.');el?.focus();return}if(name.length>24){toast('Use a shorter name.');return}if(store.profiles.length>=8){toast('The maximum is eight profiles.');return}if(store.profiles.some(x=>x.name.toLowerCase()===name.toLowerCase())){toast('That student name is already in use.');return}let p=newProfile(name);store.profiles.push(p);store.active=p.id;persist();closeModal();game=null;feedback=null;stopTicker();view='home';render();toast(`Welcome, ${name}!`)}
function changeProfile(id){const p=store.profiles.find(x=>x.id===id);if(!p)return;store.active=id;persist();closeModal();game=null;feedback=null;stopTicker();view='home';render();toast(`Now playing as ${p.name}.`)}
function deleteProfile(id){const p=store.profiles.find(x=>x.id===id);if(!p||store.profiles.length===1)return;confirmDialog('Delete '+p.name+'?',`This permanently erases ${p.name}'s local progress, gold, stars, and purchases.`,()=>{store.profiles=store.profiles.filter(x=>x.id!==id);if(store.active===id)store.active=store.profiles[0].id;persist();view='home';game=null;stopTicker();render();toast('Student profile deleted.')},'Delete Profile')}
function renderCalc(){const host=$('#calculator-root');if(!calculatorOpen||!store.settings.calculator||view!=='play'){host.innerHTML='';return}
 const style=calcLeft===null?'':`left:${calcLeft}px;top:${calcTop}px`;
 host.innerHTML=`<section class="floating-calc" id="floating-calc" style="${style}" aria-label="Draggable calculator"><div class="calc-header" id="calc-drag">▦ Magical Calculator <button class="btn btn-muted btn-small" data-action="calculator" aria-label="Close calculator">×</button></div><div class="calc-display" id="calc-display">${h(calcValue)}</div><div class="calc-buttons">${['C','(',')','÷','7','8','9','×','4','5','6','−','1','2','3','+','0','.','⌫','='].map(k=>`<button class="calc-key ${'+−×÷'.includes(k)?'op':''} ${k==='='?'equals':''}" data-action="calc-key" data-key="${h(k)}">${h(k)}</button>`).join('')}</div></section>`;
}
function evaluateMath(expr){const s=expr.replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-').replace(/\s/g,'');if(!/^[0-9.()+\-*/]+$/.test(s))throw Error('Invalid expression');let i=0;function parseAtom(){if(s[i]==='+'||s[i]==='-'){const sign=s[i++]==='-'?-1:1;return sign*parseAtom()}if(s[i]==='('){i++;let x=parseExpr();if(s[i++]!==')')throw Error('Missing )');return x}let m=/^\d*\.?\d+/.exec(s.slice(i));if(!m)throw Error('Number expected');i+=m[0].length;return Number(m[0])}function parseTerm(){let n=parseAtom();while(s[i]==='*'||s[i]==='/'){let op=s[i++],b=parseAtom();n=op==='*'?n*b:n/b}return n}function parseExpr(){let n=parseTerm();while(s[i]==='+'||s[i]==='-'){let op=s[i++],b=parseTerm();n=op==='+'?n+b:n-b}return n}let out=parseExpr();if(i!==s.length||!Number.isFinite(out))throw Error('Invalid result');return Math.round(out*1e9)/1e9}
function calcKey(key){if(key==='C')calcValue='0';else if(key==='⌫')calcValue=calcValue.slice(0,-1)||'0';else if(key==='='){try{calcValue=String(evaluateMath(calcValue))}catch{calcValue='Error'}}else calcValue=(calcValue==='0'||calcValue==='Error'?'':calcValue)+key;const el=$('#calc-display');if(el)el.textContent=calcValue;sfx('click')}
let dragState=null;
document.addEventListener('pointerdown',e=>{const drag=e.target.closest('#calc-drag');if(!drag||e.target.closest('button'))return;const panel=$('#floating-calc');if(!panel)return;const rect=panel.getBoundingClientRect();dragState={id:e.pointerId,dx:e.clientX-rect.left,dy:e.clientY-rect.top};drag.setPointerCapture(e.pointerId);e.preventDefault()});
document.addEventListener('pointermove',e=>{if(!dragState||e.pointerId!==dragState.id)return;calcLeft=Math.max(0,Math.min(window.innerWidth-90,e.clientX-dragState.dx));calcTop=Math.max(60,Math.min(window.innerHeight-55,e.clientY-dragState.dy));const el=$('#floating-calc');if(el){el.style.left=calcLeft+'px';el.style.top=calcTop+'px'}});
document.addEventListener('pointerup',e=>{if(dragState&&dragState.id===e.pointerId)dragState=null});

// Desktop: drop an ingredient image into the potion; mobile also supports simple taps.
document.addEventListener('dragstart',e=>{const img=e.target.closest('[data-gem-drag]');if(!img||!game)return;e.dataTransfer?.setData('text/plain','potion:'+img.dataset.gemDrag);if(e.dataTransfer)e.dataTransfer.effectAllowed='copy'});
document.addEventListener('dragover',e=>{if(e.target.closest('.scene')&&game){e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='copy'}});
document.addEventListener('drop',e=>{if(!game||!e.target.closest('.scene'))return;const data=e.dataTransfer?.getData('text/plain')||'';if(!data.startsWith('potion:'))return;e.preventDefault();const i=Number(data.slice(7));if(Number.isInteger(i)&&i>=0&&i<(question()?.values?.length||0))adjustGem(i,1)});


document.addEventListener('click',e=>{const hit=e.target.closest('[data-action]');if(!hit||hit.disabled)return;const act=hit.dataset.action;const modal=!!$('#overlay-root').firstElementChild;
 if(act!=='adjust'&&act!=='calc-key'&&act!=='brew'&&act!=='continue'&&act!=='retry')sfx('click');if(store.settings.music&&!audio.musicTimer)syncMusic();
 if(act==='modal'){showModal(hit.dataset.modal);return}
 if(act==='close-modal'){closeModal();return}
 if(act==='confirm-yes'){const cb=confirmAction;confirmAction=null;closeModal();if(cb)cb();return}
 if(modal&&act!=='exit-level'&&act!=='toggle-setting'&&act!=='profile-add'&&act!=='profile-switch'&&act!=='profile-delete')return;
 switch(act){
 case 'nav':navigate(hit.dataset.view);break;
 case 'world':chosenWorld=Number(hit.dataset.world);view='world';render();break;
 case 'start':beginLevel(Number(hit.dataset.level));break;
 case 'mode':store.mode=hit.dataset.mode;persist();render();break;
 case 'pause':showModal('pause');break;
 case 'exit-level':closeModal();game=null;feedback=null;stopTicker();calculatorOpen=false;view='map';render();break;
 case 'brew':handleBrew();break;
 case 'retry':feedback=null;render();$('#numeric-answer')?.focus();break;
 case 'continue':continueStage();break;
 case 'hint':useHint();break;
 case 'adjust':adjustGem(Number(hit.dataset.index),Number(hit.dataset.delta));break;
 case 'bottle':selectBottle(Number(hit.dataset.index));break;
 case 'purchase':purchase(hit.dataset.skin);break;
 case 'replay':beginLevel(game.level);break;
 case 'next-level':if(game.level===60){view='map';render()}else beginLevel(game.level+1);break;
 case 'profile-add':newStudent();break;
 case 'profile-switch':changeProfile(hit.dataset.id);break;
 case 'profile-delete':deleteProfile(hit.dataset.id);break;
 case 'toggle-setting':{const setting=hit.dataset.setting;store.settings[setting]=!store.settings[setting];persist();if(setting==='music')syncMusic();if(setting==='calculator'&&!store.settings.calculator)calculatorOpen=false;showModal('settings');break}
 case 'calculator':calculatorOpen=!calculatorOpen;if(calculatorOpen)ensureAudio();renderCalc();break;
 case 'calc-key':calcKey(hit.dataset.key);break;
 }
});
document.addEventListener('change',e=>{if(e.target.matches('.qty-input')){const q=question();if(!q?.values)return;q.values[Number(e.target.dataset.index)]=Math.max(0,Math.min(999,Math.floor(Number(e.target.value)||0)));e.target.value=q.values[Number(e.target.dataset.index)];updateTotals()}});
document.addEventListener('input',e=>{if(e.target.matches('.qty-input')){const q=question();if(q?.values){const i=Number(e.target.dataset.index);q.values[i]=Math.max(0,Math.min(999,Math.floor(Number(e.target.value)||0)));updateTotals()}}if(e.target.matches('[data-setting-range]')){const k=e.target.dataset.settingRange;store.settings[k]=Number(e.target.value);const next=e.target.nextElementSibling;if(next)next.textContent=e.target.value+'%';persist()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modalType){closeModal();return}if(e.key==='Enter'&&modalType==='profiles'&&document.activeElement?.id==='new-profile'){e.preventDefault();newStudent();return}if(e.key==='Enter'&&view==='play'&&!feedback&&!modalType&&document.activeElement?.matches('[data-answer]')){e.preventDefault();handleBrew();return}if(e.key==='Enter'&&view==='play'&&!feedback&&!modalType&&document.activeElement?.matches('.qty-input')){e.preventDefault();handleBrew();return}if(e.key===' '&&document.activeElement?.matches('.ingredient-card img[role="button"]')){e.preventDefault();adjustGem(Number(document.activeElement.dataset.index),1)}});
window.addEventListener('pagehide',persist);document.addEventListener('visibilitychange',()=>{if(document.hidden&&audio.ctx&&audio.ctx.state==='running')audio.ctx.suspend()});
persist();render();
